import{_ as e,o as l,c as t,ag as i}from"./chunks/framework.CvZZEx4j.js";const u=JSON.parse('{"title":"COT 模板","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cot-template.md","filePath":"reference/cot-template.md","lastUpdated":null}'),o={name:"reference/cot-template.md"};function r(c,a,n,s,d,h){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="cot-模板" tabindex="-1">COT 模板 <a class="header-anchor" href="#cot-模板" aria-label="Permalink to &quot;COT 模板&quot;">​</a></h1><h2 id="什么是-cot-模板" tabindex="-1">什么是 COT 模板 <a class="header-anchor" href="#什么是-cot-模板" aria-label="Permalink to &quot;什么是 COT 模板&quot;">​</a></h2><p>COT（Chain of Thought）模板是插件自动生成的一段提示词，它告诉 AI 应该以什么格式输出内容。</p><p>这段提示词会被写入一个专用的世界书（<code>galgame界面插件</code>），并以「系统提示」的方式注入到 AI 的上下文中。</p><h2 id="自动生成的内容" tabindex="-1">自动生成的内容 <a class="header-anchor" href="#自动生成的内容" aria-label="Permalink to &quot;自动生成的内容&quot;">​</a></h2><p>COT 模板会根据你当前的配置自动生成，包含：</p><ul><li>✅ 所有可用的表情列表（含自定义表情）</li><li>✅ 背景场景列表（根据你上传的背景图）</li><li>✅ TTS 音色列表和角色绑定关系</li><li>✅ 背景图来源的使用规范（本地/AI 生图/Wallhaven）</li><li>✅ 特效标签使用规则</li><li>✅ BGM 白名单</li><li>✅ 输出格式示例</li></ul><h2 id="注入世界书" tabindex="-1">注入世界书 <a class="header-anchor" href="#注入世界书" aria-label="Permalink to &quot;注入世界书&quot;">​</a></h2><ol><li>打开 <strong>设置面板</strong></li><li>点击「注入世界书」按钮</li><li>插件会自动创建/更新世界书 <code>galgame界面插件</code></li><li>世界书会以全局方式开启</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>每次你修改了资源（如添加/删除立绘、背景、音色绑定），建议重新点击「注入世界书」以更新 COT 模板。</p></div><h2 id="手动更新" tabindex="-1">手动更新 <a class="header-anchor" href="#手动更新" aria-label="Permalink to &quot;手动更新&quot;">​</a></h2><p>当你更改了以下配置后，需要重新注入：</p><ul><li>添加/删除/修改表情差分</li><li>上传/删除背景图</li><li>修改 TTS 音色绑定</li><li>切换背景图来源</li><li>修改 BGM 白名单</li></ul>',13)])])}const m=e(o,[["render",r]]);export{u as __pageData,m as default};
